#!/usr/bin/env node
// Builds packages/web:
//   css/rtl.css        [dir="rtl"] overrides auto-generated from bundle.css (postcss-rtlcss) + css/rtl-extra.css   (committed)
//   css/ism.css        tokens.css + bundle.css + states.css + scripts.css, one file                                     (committed)
// Font and asset URLs are relative to css/ (../assets/...).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';
import rtlcss from 'postcss-rtlcss';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(resolve(root, p), 'utf8');
const CHECK = process.argv.includes('--check');

const bundle = read('css/bundle.css');
// rtlcss override mode re-emits the whole stylesheet; keep only the generated [dir="rtl"] rules.
const onlyRtl = () => ({
  postcssPlugin: 'only-rtl',
  OnceExit(root) {
    root.walkAtRules((a) => { if (['import', 'font-face', 'keyframes'].includes(a.name)) a.remove(); });
    root.walkComments((c) => c.remove());
    root.walkRules((r) => { if (!r.selector.includes('[dir="rtl"]')) r.remove(); });
    root.walkAtRules((a) => { if (a.nodes && a.nodes.length === 0) a.remove(); });
  },
});
const result = await postcss([rtlcss({ mode: 'override', processUrls: false, safeBothPrefix: true }), onlyRtl()]).process(bundle, { from: undefined });
const rtl = `/* GENERATED by packages/web/scripts/build-web.mjs from bundle.css (postcss-rtlcss, override mode) + rtl-extra.css. Do not edit by hand. */\n${result.css.trim()}\n\n${read('css/rtl-extra.css').trim()}\n`;

const write = (rel, text) => {
  const abs = resolve(root, rel);
  if (CHECK) {
    let cur = '';
    try { cur = readFileSync(abs, 'utf8'); } catch {}
    if (cur !== text) { console.error(`STALE: packages/web/${rel}`); process.exitCode = 1; }
    return;
  }
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, text);
};

write('css/rtl.css', rtl);
const ism = ['tokens.css', 'bundle.css', 'states.css', 'scripts.css'].map((f) => `/* ---- ${f} ---- */\n${read('css/' + f).trim()}\n`).join('\n');
{
  write('css/ism.css', `/* ISM Design System ${JSON.parse(read('package.json')).version}: tokens + components + scripts. Fonts and assets resolve from ../assets/. */\n${ism}`);
  
}
console.log(CHECK ? 'web: css/rtl.css checked' : `web: wrote css/rtl.css (${rtl.length} bytes), css/ism.css (${ism.length} bytes)`);
